<script setup lang="ts">
import AdminStatus from '~/components/admin/AdminStatus.vue';
definePageMeta({ layout: 'admin', middleware: ['superuser'] });
const { t } = useI18n(); const { datum } = useAdminDatums(); const api = useAdminApi();
const { data, error, status, refresh } = useAdminGegevens('overzicht', api.overzicht);
const tellers = ['gebruikers', 'organisaties', 'projecten'] as const;
const aandacht = [{ key: 'proefEindigt', filter: { aandacht: 'proef' } }, { key: 'betaling', filter: { aandacht: 'betaling' } }, { key: 'alleenLezen', filter: { toegang: 'alleenLezen' } }] as const;
useHead({ title: () => `${t('admin.overzicht')} · ${t('admin.titel')}` });
</script>
<template>
  <div class="mb-7 flex flex-wrap items-start justify-between gap-4"><div><h1 class="text-2xl font-semibold">{{ t('admin.overzicht') }}</h1><p v-if="data" class="mt-2 text-sm text-muted">{{ t('admin.beoordeeldOp', { datum: datum(data.beoordeeldOp) }) }}</p></div><UButton color="neutral" variant="ghost" icon="i-lucide-refresh-cw" :loading="status === 'pending' || status === 'idle'" @click="refresh()">{{ t('admin.vernieuwen') }}</UButton></div>
  <AdminStatus :fout="error" :bezig="status === 'pending' || !data" @opnieuw="refresh()">
    <template v-if="data">
      <dl class="mb-8 grid grid-cols-1 divide-y divide-default border-y border-default sm:grid-cols-3 sm:divide-x sm:divide-y-0"><div v-for="soort in tellers" :key="soort" class="py-5 sm:px-5 first:sm:pl-0"><dt class="text-sm text-muted">{{ t(`admin.${soort}`) }}</dt><dd class="mt-1"><NuxtLink :to="`/admin/${soort}`" class="text-2xl font-semibold tabular-nums text-primary hover:underline">{{ data.aantallen[soort] }}</NuxtLink></dd></div></dl>
      <p class="mb-8 text-sm text-muted">{{ t('admin.activiteit30dagen', { gebruikers: data.aantallen.nieuweGebruikers, organisaties: data.aantallen.nieuweOrganisaties, projecten: data.aantallen.gewijzigdeProjecten }) }}</p>
      <section class="mb-8"><h2 class="mb-3 text-xl font-semibold">{{ t('admin.bedrijfstoegang') }}</h2><p v-if="!data.billing" class="mb-3 text-sm text-muted">{{ t('admin.billingUit') }}</p><ul class="flex flex-wrap gap-x-6 gap-y-3"><li v-for="(aantal, groep) in data.toegang" :key="groep"><NuxtLink :to="{ path: '/admin/organisaties', query: { toegang: groep } }" class="text-sm hover:underline"><span class="mr-2 font-semibold tabular-nums">{{ aantal }}</span>{{ t(`admin.groepen.${groep}`) }}</NuxtLink></li></ul></section>
      <div class="grid gap-x-10 gap-y-8 lg:grid-cols-2">
        <section v-for="a in aandacht" :key="a.key" class="border-t border-default pt-6"><h2 class="mb-4 text-lg font-semibold">{{ t(`admin.aandacht.${a.key}`) }} <span class="text-sm font-normal text-muted">({{ data.aandacht[a.key].totaal }})</span></h2><p v-if="!data.aandacht[a.key].items.length" class="text-sm text-muted">{{ t('admin.geenAandacht') }}</p><ul v-else class="divide-y divide-default"><li v-for="bedrijf in data.aandacht[a.key].items" :key="bedrijf.id" class="py-3 first:pt-0"><NuxtLink :to="`/admin/organisaties/${bedrijf.id}`" class="font-medium text-primary hover:underline">{{ bedrijf.naam }}</NuxtLink><p class="mt-1 text-sm text-muted">{{ t(`admin.redenen.${bedrijf.toegang.reden}`) }}</p></li></ul><NuxtLink v-if="data.aandacht[a.key].totaal > 5" :to="{ path: '/admin/organisaties', query: a.filter }" class="text-sm text-primary underline">{{ t('admin.alleResultaten') }}</NuxtLink></section>
        <section class="border-t border-default pt-6"><h2 class="mb-4 text-lg font-semibold">{{ t('admin.opvolging') }} <span class="text-sm font-normal text-muted">({{ data.opvolging.totaal }})</span></h2><p v-if="!data.opvolging.items.length" class="text-sm text-muted">{{ t('admin.geenOpvolging') }}</p><ul v-else class="divide-y divide-default"><li v-for="n in data.opvolging.items" :key="n.id" class="py-3 first:pt-0"><NuxtLink :to="n.projectId ? `/admin/projecten/${n.projectId}` : `/admin/organisaties/${n.organisatieId}`" class="line-clamp-2 text-primary hover:underline">{{ n.tekst }}</NuxtLink><p class="mt-1 text-xs text-muted">{{ datum(n.opvolgdatum, false) }} · {{ n.auteur.naam }}</p></li></ul><NuxtLink v-if="data.opvolging.totaal > data.opvolging.items.length" to="/admin/opvolging" class="text-sm text-primary underline underline-offset-4">{{ t('admin.alleResultaten') }}</NuxtLink></section>
        <section class="border-t border-default pt-6"><h2 class="mb-4 text-lg font-semibold">{{ t('admin.recenteProjecten') }}</h2><p v-if="!data.recenteProjecten.length" class="text-sm text-muted">{{ t('admin.geenResultaten') }}</p><ul class="space-y-3"><li v-for="p in data.recenteProjecten" :key="p.id"><NuxtLink :to="`/admin/projecten/${p.id}`" class="font-medium text-primary hover:underline">{{ p.naam }}</NuxtLink><p class="mt-1 text-sm text-muted">{{ p.organisatieNaam }} · {{ datum(p.gewijzigd) }}</p></li></ul></section>
        <section class="border-t border-default pt-6"><h2 class="mb-4 text-lg font-semibold">{{ t('admin.recenteCorrecties') }}</h2><p v-if="!data.recenteCorrecties.length" class="text-sm text-muted">{{ t('admin.geenAudit') }}</p><ul class="space-y-3"><li v-for="a in data.recenteCorrecties" :key="a.id"><NuxtLink :to="`/admin/audit/${a.id}`" class="font-medium text-primary hover:underline">{{ t(`admin.acties.${a.actie.replaceAll('.', '_')}`) }}</NuxtLink><p class="mt-1 text-sm text-muted">{{ a.actor.naam }} · {{ datum(a.tijd) }}</p></li></ul></section>
      </div>
    </template>
  </AdminStatus>
</template>
